#endif
public struct FfiConverterTypeCanvasEditor: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = CanvasEditor

    public static func lift(_ handle: UInt64) throws -> CanvasEditor {
        return CanvasEditor(unsafeFromHandle: handle)
    }

    public static func lower(_ value: CanvasEditor) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CanvasEditor {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: CanvasEditor, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCanvasEditor_lift(_ handle: UInt64) throws -> CanvasEditor {
    return try FfiConverterTypeCanvasEditor.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCanvasEditor_lower(_ value: CanvasEditor) -> UInt64 {
    return FfiConverterTypeCanvasEditor.lower(value)
}






/**
 * One `.flow.json`: changed by batches of ops, each one undo step, written
 * on save beside the file and renamed over it.
 */
public protocol FlowDocumentProtocol: AnyObject, Sendable {
    
    /**
     * Apply a batch of ops (a JSON array) as one undo step, all of it or
     * none, checked against `catalogue`. Answers what it did as JSON:
     * `{"changed": bool, "added": [ids]}`.
     */
    func apply(opsJson: String, catalogue: NodeCatalogue) throws  -> String
    
    func canRedo()  -> Bool
    
    func canUndo()  -> Bool
    
    /**
     * The flow now, in the `.flow.json` shape.
     */
    func flowJson()  -> String
    
    /**
     * The graph a run sends, as JSON, or the problems that stop it.
     */
    func graph(catalogue: NodeCatalogue, modelsJson: String?) throws  -> String
    
    /**
     * The graph a run to `node` sends: only what that node needs, every
     * other output left out. A node that is not an output itself is
     * followed by a Preview Image — after a VAE Decode when it makes a
     * latent — so the run shows what it makes. The flow itself is not
     * changed.
     */
    func graphTo(node: String, catalogue: NodeCatalogue, modelsJson: String?) throws  -> GraphTo
    
    func isDirty()  -> Bool
    
    /**
     * Whether it is saved sealed.
     */
    func isSealed()  -> Bool
    
    func path()  -> String
    
    /**
     * Everything that stops the flow running, as a JSON array of
     * `{"node", "input", "message"}`. `models_json` is the server's model
     * lists when known.
     */
    func problems(catalogue: NodeCatalogue, modelsJson: String?) throws  -> String
    
    func redo()  -> Bool
    
    /**
     * Replace the whole flow as one undo step.
     */
    func replace(flowJson: String) throws 
    
    /**
     * The file changed under it: take what it says, as an undoable step.
     */
    func reread() throws  -> Bool
    
    /**
     * Write it, whole or not at all.
     */
    func save() throws 
    
    /**
     * Save it sealed with `key` from now on, or plain without. For a flow
     * not yet written, or written somewhere new: one already on disk would
     * leave its other file behind.
     */
    func sealWith(key: SealKey?) 
    
    /**
     * The flow as its file's text.
     */
    func text()  -> String
    
    func undo()  -> Bool
    
}
